    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    # Merge overlapping/touching intervals in b
    if b:
        b_sorted = sorted(b)
        b_merged = []
        current_start, current_end = b_sorted[0]
        for start, end in b_sorted[1:]:
            if start <= current_end:
                current_end = max(current_end, end)
            else:
                b_merged.append([current_start, current_end])
                current_start, current_end = start, end
        b_merged.append([current_start, current_end])
    else:
        b_merged = []

