            current_end = max(current_end, end)
        else:
            a_merged.append([current_start, current_end])
            current_start, current_end = start, end
    a_merged.append([current_start, current_end])

    # Subtract b_merged from a_merged
    result = []
    for a_start, a_end in a_merged:
        current_intervals = [[a_start, a_end]]
        for b_start, b_end in b_merged:
            new_intervals = []
            for interval_start, interval_end in current_intervals:
                if b_end <= interval_start or b_start >= interval_end:
